import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"Este portafolio: un diseño, dos idiomas","description":"La metahistoria: cómo este sitio fue especificado, clonado del sistema de diseño de easy-vibe, traducido a dos idiomas y enviado por un equipo de agentes.","frontmatter":{"title":"Este portafolio: un diseño, dos idiomas","description":"La metahistoria: cómo este sitio fue especificado, clonado del sistema de diseño de easy-vibe, traducido a dos idiomas y enviado por un equipo de agentes."},"headers":[],"relativePath":"es/vibe-stories/story-4/index.md","filePath":"es/vibe-stories/story-4/index.md"}`),a={name:`es/vibe-stories/story-4/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="este-portafolio-un-diseno-dos-idiomas" tabindex="-1">Este portafolio: un diseño, dos idiomas <a class="header-anchor" href="#este-portafolio-un-diseno-dos-idiomas" aria-label="Permalink to “Este portafolio: un diseño, dos idiomas”">​</a></h1><p>Estás viendo el proyecto más autorreferencial de mi portafolio: <strong>este sitio web</strong>. Es una reconstrucción fiel del sistema de diseño de <a href="https://datawhalechina.github.io/easy-vibe/en/" target="_blank" rel="noreferrer">easy-vibe</a> — el mismo tema VitePress, layout y comportamiento — con cada texto e imagen reemplazados por mi propio contenido, en <strong>dos idiomas</strong>: English y Español.</p><h2 id="por-que-clonar-el-sitio-de-un-curso" tabindex="-1">Por qué clonar el sitio de un curso <a class="header-anchor" href="#por-que-clonar-el-sitio-de-un-curso" aria-label="Permalink to “Por qué clonar el sitio de un curso”">​</a></h2><p>Porque es honesto sobre lo que es la buena ingeniería: encuentra algo excelente, entiéndelo por completo, y luego adáptalo con respeto. La portada estilo Apple, la navegación de cristal, el tagline tecleado, el carrusel de historias con marco de MacBook — todo fue estudiado, portado y anclado a una versión más nueva del motor, y luego llenado con una vida para la que nunca fue escrito.</p><h2 id="lo-que-lo-hizo-no-trivial" tabindex="-1">Lo que lo hizo no trivial <a class="header-anchor" href="#lo-que-lo-hizo-no-trivial" aria-label="Permalink to “Lo que lo hizo no trivial”">​</a></h2><ul><li><strong>Una capa i18n real</strong> — el selector de idioma, las rutas por locale y el chrome de UI localizado (panel de ajustes, diapositivas, toggles de código) funcionan de punta a punta.</li><li><strong>Wordmark personalizado</strong> — el logo caligráfico &quot;Usf&quot; se generó de una fuente real a paths SVG para que la pantalla de bienvenida conservara su efecto de dibujo animado.</li><li><strong>Catorce ilustraciones nuevas</strong> — cada portada de tarjeta e historia se generó para coincidir con la estética pastel del tema.</li><li><strong>Ensamblado por equipo de agentes</strong> — el porte del tema, el contenido, las traducciones y el despliegue corrieron como flujos de trabajo de agentes paralelos, coordinados a la manera <a href="/Usf/es/agentic/hermes/">Hermes</a>.</li></ul><p>La fuente de la verdad vive en <a href="https://github.com/Godde3s/Usf" target="_blank" rel="noreferrer">github.com/Godde3s/Usf</a> — pública, naturalmente. Si estás leyendo esto en el sitio en vivo, el pipeline funcionó; si lo lees en GitHub, el pipeline está a un <code>vitepress build</code> de distancia.</p>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};